de\": \"^22.12.0\",\r\n    \"typescript\": \"^5.7.0\"\r\n  }\r\n}\r\n\n```\n\n### src\\blobService.ts\n```\nimport * as fs from \"fs\";\r\nimport {\r\n  BlobServiceClient,\r\n  ContainerClient,\r\n  BlockBlobClient,\r\n  BlobItem,\r\n  BlobLeaseClient,\r\n  BlockBlobUploadStreamOptions,\r\n} from \"@azure/storage-blob\";\r\n\r\n/** Metadata key-value pairs attached to a blob. */\r\nexport type BlobMetadata = Record\u003cstring, string\u003e;\r\n\r\n/** Index tags for server-side querying (Blob Index). */\r\nexport type BlobTags = Record\u003cstring, string\u003e;\r\n\r\nexport interface UploadOptions {\r\n  metadata?: BlobMetadata;\r\n  tags?: BlobTags;\r\n}\r\n\r\nexport interface LeaseUploadOptions extends UploadOptions {\r\n  /** Duration of the lease in seconds (15-60, or -1 for infinite). */\r\n  leaseDurationSeconds?: number;\r\n}\r\n\r\n/**\r\n * Reusable service that wraps Azure Blob Storage operations.\r\n *\r\n * All operations target a single container whose name is provided at\r\n * construction time. The container is created automatically if it does\r\n * not already exist.\r\n */\r\nexport class BlobStorageService {\r\n  private readonly containerClient: ContainerClient;\r\n\r\n  constructor(\r\n    private readonly serviceClient: BlobServiceClient,\r\n    private readonly containerName: string\r\n  ) {\r\n    this.containerClient = this.serviceClient.getContainerClient(\r\n      this.containerName\r\n    );\r\n  }\r\n\r\n  /** Ensure the target container exists. */\r\n  async ensureContainer(): Promise\u003cvoid\u003e {\r\n    await this.containerClient.createIfNotExists();\r\n  }\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // Upload\r\n  // ---------------------------------------------------------------------------\r\n\r\n  /**\r\n   * Upload a file to blob storage using streaming so that arbitrarily large\r\n   * files can be uploaded without loading them entirely into memory.\r\n   *\r\n   * @param blobName  Destination blob name (may include virtual directory path).\r\n   * @param filePath  Local path to the file to upload.\r\n   * @param options   Optional metadata and index tags.\r\n   */\r\n  async upload(\r\n    blobName: string,\r\n    filePath: string,\r\n    options: UploadOptions = {}\r\n  ): Promise\u003cvoid\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    const readStream = fs.createReadStream(filePath);\r\n\r\n    // 4 MiB per block, up to 4 concurrent uploads — keeps memory bounded\r\n    // even for multi-gigabyte files.\r\n    const bufferSize = 4 * 1024 * 1024;\r\n    const maxConcurrency = 4;\r\n\r\n    const uploadOptions: BlockBlobUploadStreamOptions = {};\r\n    if (options.metadata) {\r\n      uploadOptions.metadata = options.metadata;\r\n    }\r\n    if (options.tags) {\r\n      uploadOptions.tags = options.tags;\r\n    }\r\n\r\n    await blockBlobClient.uploadStream(\r\n      readStream,\r\n      bufferSize,\r\n      maxConcurrency,\r\n      uploadOptions\r\n    );\r\n  }\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // Download\r\n  // ---------------------------------------------------------------------------\r\n\r\n  /**\r\n   * Download a blob and return its contents as a string.\r\n   *\r\n   * For very large blobs you would typically stream to disk; this helper is\r\n   * intended for reasonably-sized text blobs.\r\n   */\r\n  async download(blobName: string): Promise\u003cstring\u003e {\r\n    const blobClient = this.containerClient.getBlobClient(blobName);\r\n    const response = await blobClient.download(0);\r\n\r\n    if (!response.readableStreamBody) {\r\n      throw new Error(`Blob \"${blobName}\" has no readable stream body.`);\r\n    }\r\n\r\n    return await streamToString(response.readableStreamBody);\r\n  }\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // List\r\n  // ---------------------------------------------------------------------------\r\n\r\n  /**\r\n   * List all blobs in the container.\r\n   *\r\n   * Returns the full set of {@link BlobItem} objects so callers can inspect\r\n   * names, metadata, tags, etc.\r\n   */\r\n  async listBlobs(): Promise\u003cBlobItem[]\u003e {\r\n    const blobs: BlobItem[] = [];\r\n    for await (const blob of this.containerClient.listBlobsFlat()) {\r\n      blobs.push(blob);\r\n    }\r\n    return blobs;\r\n  }\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // Delete\r\n  // ---------------------------------------------------------------------------\r\n\r\n  /** Delete a blob. Does nothing if the blob does not exist. */\r\n  async delete(blobName: string): Promise\u003cvoid\u003e {\r\n    const blobClient = this.containerClient.getBlobClient(blobName);\r\n    await blobClient.deleteIfExists();\r\n  }\r\n\r\n  // ---------------------------------------------------------------------------\r\n  // Lease-protected upload (optimistic concurrency)\r\n  // ---------------------------------------------------------------------------\r\n\r\n  /**\r\n   * Acquire a lease on an existing blob, overwrite it while holding the lease,\r\n   * then release the lease.  This prevents concurrent writers from silently\r\n   * overwriting each other's changes.\r\n   *\r\n   * @param blobName              The blob to update.\r\n   * @param filePath              Local file whose contents will replace the blob.\r\n   * @param options               Optional metadata, tags and lease duration.\r\n   * @returns                     The lease ID that was used.\r\n   */\r\n  async uploadWithLease(\r\n    blobName: string,\r\n    filePath: string,\r\n    options: LeaseUploadOptions = {}\r\n  ): Promise\u003cstring\u003e {\r\n    const blobClient = this.containerClient.getBlobClient(blobName);\r\n    const blockBlobClient: BlockBlobClient =\r\n      this.containerClient.getBlockBlobClient(blobName);\r\n    const leaseClient: BlobLeaseClient = blobClient.getBlobLeaseClient();\r\n\r\n    const leaseDuration = options.leaseDurationSeconds ?? 30;\r\n\r\n    // Acquire the lease — this will fail with 409 if another writer already\r\n    // holds the lease, which is the desired concurrency-safe behaviour.\r\n    const leaseResponse = await leaseClient.acquireLease(leaseDuration);\r\n    const leaseId = leaseResponse.leaseId!;\r\n\r\n    try {\r\n      const readStream = fs.createReadStream(filePath);\r\n      const bufferSize = 4 * 1024 * 1024;\r\n      const maxConcurrency = 4;\r\n\r\n      const uploadOptions: BlockBlobUploadStreamOptions = {\r\n        conditions: { leaseId },\r\n      };\r\n      if (options.metadata) {\r\n        uploadOptions.metadata = options.metadata;\r\n      }\r\n      if (options.tags) {\r\n        uploadOptions.tags = options.tags;\r\n      }\r\n\r\n      await blockBlobClient.uploadStream(\r\n        readStream,\r\n        bufferSize,\r\n        maxConcurrency,\r\n        uploadOptions\r\n      );\r\n    } finally {\r\n      // Always release the lease, even if the upload fails.\r\n      await leaseClient.releaseLease();\r\n    }\r\n\r\n    return leaseId;\r\n  }\r\n}\r\n\r\n// ---------------------------------------------------------------------------\r\n// Helpers\r\n// ---------------------------------------------------------------------------\r\n\r\n/** Drain a Node.js readable stream into a UTF-8 string. */\r\nfunction streamToString(stream: NodeJS.ReadableStream): Promise\u003cstring\u003e {\r\n  return new Promise((resolve, reject) =\u003e {\r\n    const chunks: Buffer[] = [];\r\n    stream.on(\"data\", (chunk: Buffer) =\u003e chunks.push(chunk));\r\n    stream.on(\"end\", () =\u003e resolve(Buffer.concat(chunks).toString(\"utf-8\")));\r\n    stream.on(\"error\", reject);\r\n  });\r\n}\r\n\n```\n\n### src\\config.ts\n```\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\nimport {\r\n  BlobServiceClient,\r\n  StorageRetryPolicyType,\r\n  StorageRetryOptions,\r\n} from \"@azure/storage-blob\";\r\nimport { setLogLevel, AzureLogger } from \"@azure/logger\";\r\n\r\nexport interface BlobStorageConfig {\r\n  /** Maximum number of retries for failed requests. */\r\n  maxRetries?: number;\r\n  /** Maximum delay between retries in milliseconds. */\r\n  maxRetryDelayMs?: number;\r\n  /**\r\n   * Azure SDK log level for debugging.\r\n   * One of: \"verbose\", \"info\", \"warning\", \"error\".\r\n   */\r\n  logLevel?: \"verbose\" | \"info\" | \"warning\" | \"error\";\r\n}\r\n\r\nconst DEFAULT_MAX_RETRIES = 3;\r\nconst DEFAULT_MAX_RETRY_DELAY_MS = 4000;\r\n\r\n/**\r\n * Creates a BlobServiceClient authenticated via DefaultAzureCredential\r\n * (managed identity / Azure CLI / environment credentials — no keys).\r\n *\r\n * The storage account endpoint is read from the AZURE_STORAGE_ACCOUNT_URL\r\n * environment variable (e.g. \"https://\u003caccount\u003e.blob.core.windows.net\").\r\n */\r\nexport function createBlobServiceClient(\r\n  config: BlobStorageConfig = {}\r\n): BlobServiceClient {\r\n  const accountUrl = process.env.AZURE_STORAGE_ACCOUNT_URL;\r\n  if (!accountUrl) {\r\n    throw new Error(\r\n      \"Environment variable AZURE_STORAGE_ACCOUNT_URL is required \" +\r\n        '(e.g. \"https://\u003caccount\u003e.blob.core.windows.net\").'\r\n    );\r\n  }\r\n\r\n  const logLevel =\r\n    config.logLevel ??\r\n    (process.env.AZURE_LOG_LEVEL as BlobStorageConfig[\"logLevel\"]);\r\n  if (logLevel) {\r\n    setLogLevel(logLevel);\r\n    AzureLogger.log = (...args) =\u003e {\r\n      console.log(\"[AzureSDK]\", ...args);\r\n    };\r\n  }\r\n\r\n  const retryOptions: StorageRetryOptions = {\r\n    retryPolicyType: StorageRetryPolicyType.EXPONENTIAL,\r\n    maxTries: config.maxRetries ?? DEFAULT_MAX_RETRIES,\r\n    retryDelayInMs: 500,\r\n    maxRetryDelayInMs: config.maxRetryDelayMs ?? DEFAULT_MAX_RETRY_DELAY_MS,\r\n  };\r\n\r\n  const credential = new DefaultAzureCredential();\r\n\r\n  return new BlobServiceClient(accountUrl, credential, {\r\n    retryOptions,\r\n  });\r\n}\r\n\n```\n\n### src\\main.ts\n```\nimport * as fs from \"fs\";\r\nimport * as os from \"os\";\r\nimport * as path from \"path\";\r\nimport { createBlobServiceClient } from \"./config\";\r\nimport { BlobStorageService } from \"./blobService\";\r\n\r\nconst CONTAINER_NAME = \"demo-container\";\r\nconst BLOB_NAME = \"demo/sample.txt\";\r\n\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  // ── 1. Initialise client \u0026 service ──────────────────────────────────────\r\n  console.log(\"=== Azure Blob Storage Manager Demo ===\\n\");\r\n\r\n  const serviceClient = createBlobServiceClient({\r\n    maxRetries: 4,\r\n    maxRetryDelayMs: 5000,\r\n  });\r\n\r\n  const blobService = new BlobStorageService(serviceClient, CONTAINER_NAME);\r\n  await blobService.ensureContainer();\r\n  console.log(`✓ Container \"${CONTAINER_NAME}\" is ready.\\n`);\r\n\r\n  // ── 2. Create a temporary sample file ───────────────────────────────────\r\n  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), \"blob-demo-\"));\r\n  const sampleFile = path.join(tmpDir, \"sample.txt\");\r\n  fs.writeFileSync(sampleFile, \"Hello from Azure Blob Storage Manager!\\n\");\r\n\r\n  // ── 3. Upload with metadata \u0026 index tags ────────────────────────────────\r\n  console.log(`Uploading \"${BLOB_NAME}\" …`);\r\n  await blobService.upload(BLOB_NAME, sampleFile, {\r\n    metadata: { createdBy: \"demo\", purpose: \"testing\" },\r\n    tags: { environment: \"dev\", project: \"blob-manager\" },\r\n  });\r\n  console.log(\"✓ Upload complete.\\n\");\r\n\r\n  // ── 4. List blobs ──────────────────────────────────────────────────────\r\n  console.log(\"Listing blobs in container:\");\r\n  const blobs = await blobService.listBlobs();\r\n  for (const blob of blobs) {\r\n    console.log(`  • ${blob.name}`);\r\n  }\r\n  console.log();\r\n\r\n  // ── 5. Download \u0026 print ─────────────────────────────────────────